import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Handl SDK Generator — WebIDL / JS Backend","description":"","frontmatter":{"title":"Handl SDK Generator — WebIDL / JS Backend","type":"adr","date":"2026-10-28T00:00:00.000Z","status":"proposed","status_note":"Proposed."},"headers":[],"relativePath":"web/project/adrs/0113-handl-sdkgen-webidl-js.md","filePath":"vendored/web/project/adrs/0113-handl-sdkgen-webidl-js.md"}`),a={name:`web/project/adrs/0113-handl-sdkgen-webidl-js.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0113-handl-sdk-generator-—-webidl-js-backend" tabindex="-1">ADR-0113: Handl SDK Generator — WebIDL / JS Backend <a class="header-anchor" href="#adr-0113-handl-sdk-generator-—-webidl-js-backend" aria-label="Permalink to “ADR-0113: Handl SDK Generator — WebIDL / JS Backend”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Add a <code>plugin-sdkgen-backend-webidl</code> crate that parses WebIDL files and produces <code>SdkgenModule</code> records.</p><ul><li>The backend consumes one or more <code>.webidl</code> files (e.g. the W3C specs).</li><li>The <code>client_package</code> for the generated adapter is <code>js</code>.</li><li>The adapter uses <code>js.call</code> / <code>js.errno()</code> primitives (a new <code>js</code> client package) to invoke foreign JS functions at runtime.</li><li>Map common WebIDL types to Handl types: <ul><li><code>long</code> / <code>long long</code> → <code>Int</code> (<code>i32</code> / <code>i64</code>)</li><li><code>double</code> / <code>float</code> → <code>Float</code> (<code>f64</code> / <code>f32</code>)</li><li><code>DOMString</code> / <code>USVString</code> → <code>String</code> (<code>js_string</code>)</li><li><code>ArrayBufferView</code> / <code>BufferSource</code> → <code>Bytes</code> (<code>js_bytes</code>)</li><li><code>object</code> / <code>any</code> / interface references → <code>Handle</code> (<code>js_object</code>)</li><li><code>void</code> → <code>()</code></li></ul></li><li>Support <code>interface</code>, <code>dictionary</code>, <code>enum</code>, <code>callback function</code>, and <code>namespace</code> (static methods).</li><li>The first target runtime is <strong>Deno / Browser</strong> because both expose standard Web APIs without an extra native binding step. Node support can follow later.</li></ul><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p><a href="./0107-handl-sdk-generator.html">ADR-0107 — Handl SDK Generator</a> established a backend-agnostic <code>SdkgenModule</code> IR and a port-adapter emitter. The C backend (<code>plugin-sdkgen-backend-c</code>) is the first concrete implementation. The next high-priority target is the Web platform: Handl running in browsers, Deno, or Node must be able to call existing Web APIs (WebGL, WebGPU, DOM, etc.) and first-class <code>.webidl</code> definitions.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li>none recorded — legacy record; the design doc lists what was deferred.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Handl can consume the Web platform API surface directly.</li><li>A <code>js</code> client package must be designed and implemented, paralleling <code>ffi</code> and</li><li>WebIDL overloads and optional arguments require a name-mangling / defaulting</li><li>This backend is, by request, the highest-priority future backend in the SDK</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>plugin-sdkgen-backend-webidl</code> — where this is true.</li><li><code>plugin-sdkgen-backend-c</code> — where this is true.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The full record (context, tables, phases, trade-offs): <a href="./../design/0113-handl-sdkgen-webidl-js.html"><code>design/0113-handl-sdkgen-webidl-js.md</code></a>.</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};